        Date from = input.from() == null ? null : Date.valueOf(input.from());
        if (jdbc.update("UPDATE rate SET pct = ? WHERE sheet = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                input.pct(), sheet, input.grade(), from) == 0) {
